import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;
  late final FocusNode _focusNode;

  late Future<List<CurrencyModel>> _currencyListFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    _focusNode.dispose();
    super.dispose();
  }

  // ------------------------------------------------------------------
  // Lifecycle — обновление при возврате на экран
  // ------------------------------------------------------------------

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused) {
      _focusNode.unfocus();
    } else if (state == AppLifecycleState.resumed && !_focusNode.hasFocus) {
      _refreshData();
    }
  }

  // ------------------------------------------------------------------
  // Animation / Data
  // ------------------------------------------------------------------

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _refreshData() async {
    setState(() {
      _allCurrencies = [];
      _filteredCurrenciesNotifier.value = [];
      _currentPage = 0;
      _hasMore = true;
    });
    await _initData();
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore) return;
    setState(() => _isLoadingMore = true);
    final CurrencyPageRequest nextPage = CurrencyPageRequest(base: 'USD', page: _currentPage + 1);
    try {
      await context.read<CurrencyRepository>().fetchRates(nextPage).then((CurrencyPage page) {
        final List<CurrencyModel> items = [..._allCurrencies, ...page.items];
        _currentPage = page.page;
        _hasMore = page.hasMore;
        _allCurrencies = items;

        // При открытом поиске — фильтруем заново
        final String query = '';
        if (query.isEmpty) {
          _filteredCurrenciesNotifier.value = items.toList(growable: false);
        } else {
          final String lowerQuery = query.toLowerCase();
          final List<CurrencyModel> result = items.where((CurrencyModel currency) =>
              currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery)).toList(growable: false);
          _filteredCurrenciesNotifier.value = result;
        }

        context.read<CurrencyRepository>().saveCurrencyList(items);
      });
    } finally {
      if (mounted) setState(() => _isLoadingMore = false);
    }
  }

  void _initData() async {
    final CurrencyPageRequest request = const CurrencyPageRequest(base: 'USD');
    await context.read<CurrencyRepository>().fetchRates(request).then((CurrencyPage page) {
      final List<CurrencyModel> value = page.items;
      _allCurrencies = value;
      _filteredCurrenciesNotifier.value = value;
      _currentPage = page.page;
      _hasMore = page.hasMore;

      _fadeController.forward();

      context.read<CurrencyRepository>().saveCurrencyList(value);
    });
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) =>
        currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery));
    _filteredCurrenciesNotifier.value = result.toList(growable: false);
  }

  // ------------------------------------------------------------------
  // Build
  // ------------------------------------------------------------------

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: _currencyListFuture,
        builder: (BuildContext context, AsyncSnapshot<List<CurrencyModel>> snapshot) {
          final List<CurrencyModel>? data = snapshot.data;
          if (data == null) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_hasMore ? 1 : 0), // +1 для кнопки "Показать ещё"
                        itemBuilder: (BuildContext context, int index) {
                          if (index == data.length) {
                            // Кнопка «Показать ещё» — показываем только если есть следующие страницы
                            return Padding(
                              padding: const EdgeInsets.only(top: 16),
                              child: Center(
                                child: _isLoadingMore
                                    ? const CircularProgressIndicator()
                                    : OutlinedButton(
                                        onPressed: _loadMore,
                                        child: Text(context.loc.showMore),
                                      ),
                              ),
                            );
                          }
                          final CurrencyModel currency = data[index];
                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
